import { getHostname, isExternal, isMailTo, isSubDomain, isURLProtonInternal } from '@proton/components/helpers/url';

describe('isSubDomain', function () {
    it('should detect that same hostname is a subDomain', () => {
        const hostname = 'mail.proton.me';
        expect(isSubDomain(hostname, hostname)).toBeTruthy();
    });

    it('should detect that domain is a subDomain', () => {
        const hostname = 'mail.proton.me';
        const domain = 'proton.me';
        expect(isSubDomain(hostname, domain)).toBeTruthy();
    });

    it('should detect that domain is not a subDomain', () => {
        const hostname = 'mail.proton.me';
        const domain = 'whatever.com';
        expect(isSubDomain(hostname, domain)).toBeFalsy();
    });
});

describe('getHostname', function () {
    it('should give the correct hostname', () => {
        const hostname = 'mail.proton.me';
        const url = `https://${hostname}/u/0/inbox`;
        expect(getHostname(url)).toEqual(hostname);
    });
});

describe('isMailTo', function () {
    it('should detect that the url is a mailto link', () => {
        const url = 'mailto:mail@proton.me';
        expect(isMailTo(url)).toBeTruthy();
    });

    it('should detect that the url is not a mailto link', () => {
        const url = 'https://proton.me';
        expect(isMailTo(url)).toBeFalsy();
    });
});

describe('isExternal', function () {
    const windowHostname = 'mail.proton.me';

    beforeEach(() => {
        global.window = Object.create(window);
        Object.defineProperty(window, 'location', {
            value: {
                hostname: windowHostname,
            },
        });
    });

    it('should detect that the url is not external', () => {
        const url1 = 'https://mail.proton.me';
        expect(window.location.hostname).toEqual(windowHostname);
        expect(isExternal(url1)).toBeFalsy();
    });

    it('should detect that the url is external', () => {
        const url = 'https://url.whatever.com';
        expect(window.location.hostname).toEqual(windowHostname);
        expect(isExternal(url)).toBeTruthy();
    });

    it('should detect that the mailto link is not external', () => {
        const url = 'mailto:mail@proton.me';
        expect(window.location.hostname).toEqual(windowHostname);
        expect(isExternal(url)).toBeFalsy();
    });
});

describe('isProtonInternal', function () {
    const windowHostname = 'mail.proton.me';

    beforeEach(() => {
        global.window = Object.create(window);
        Object.defineProperty(window, 'location', {
            value: {
                hostname: windowHostname,
            },
        });
    });

    it('should detect that the url is proton internal', () => {
        const url1 = 'https://mail.proton.me';
        const url2 = 'https://calendar.proton.me';

        expect(isURLProtonInternal(url1)).toBeTruthy();
        expect(isURLProtonInternal(url2)).toBeTruthy();
    });

    it('should detect that the url is not proton internal', () => {
        const url = 'https://url.whatever.com';

        expect(isURLProtonInternal(url)).toBeFalsy();
    });
});

import { useState } from 'react';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { updateConfirmLink } from '@proton/shared/lib/api/mailSettings';
import { isEdge, isIE11, openNewTab } from '@proton/shared/lib/helpers/browser';
import { rtlSanitize } from '@proton/shared/lib/helpers/string';
import { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';

import { useApi, useEventManager } from '../../hooks';
import { Form } from '../form';
import { Checkbox } from '../input';
import { Label } from '../label';
import { Href } from '../link';
import { ModalProps, ModalTwo, ModalTwoContent, ModalTwoFooter, ModalTwoHeader } from '../modalTwo';

interface Props extends ModalProps {
    link?: string;
    isOutside?: boolean;
    isPhishingAttempt?: boolean;
}

const LinkConfirmationModal = ({ link = '', isOutside = false, isPhishingAttempt = false, ...rest }: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const [dontAskAgain, setDontAskAgain] = useState(false);
    const [understandRisk, setUnderstandRisk] = useState(false);

    const { onClose } = rest;

    // https://jira.protontech.ch/browse/SEC-574
    const linkToShow = rtlSanitize(link);

    // Both are not able to open the link
    const punyCodeLink = /:\/\/xn--/.test(link);

    const punyCodeLinkText =
        isEdge() || isIE11()
            ? c('Info')
                  .t`This link may be a homograph attack and cannot be opened by Edge browsers. If you are certain the link is legitimate, please use a different browser to open it.`
            : c('Info')
                  .t`This link may be a homograph attack. Please verify this is the link you wish to visit, or don't open it.`;

    const handleConfirm = async () => {
        openNewTab(link);

        if (dontAskAgain && !isOutside) {
            await api(updateConfirmLink(0));
            await call();
        }

        onClose?.();
    };

    const content = isPhishingAttempt ? (
        <>
            {`${c('Info')
                .t`This link leads to a website that might be trying to steal your information, such as passwords and credit card details.`} `}
            <br />
            <span className="text-bold text-break">{linkToShow}</span>

            <Label className="flex">
                <Checkbox
                    className="mr0-5"
                    checked={understandRisk}
                    onChange={() => setUnderstandRisk(!understandRisk)}
                />
                {c('Label').t`I understand the risk`}
            </Label>
        </>
    ) : (
        <>
            {`${c('Info').t`You are about to open another browser tab and visit:`} `}
            <span className="text-bold text-break">{linkToShow}</span>

            {punyCodeLink && (
                <>
                    {`${punyCodeLinkText} `}
                    <Href url={getKnowledgeBaseUrl('/homograph-attacks')} title="What are homograph attacks?">
                        {c('Info').t`Learn more`}
                    </Href>
                </>
            )}

            {!isOutside && (
                <Label className="flex">
                    <Checkbox
                        checked={dontAskAgain}
                        onChange={() => setDontAskAgain(!dontAskAgain)}
                        className="mr0-5"
                    />
                    {c('Label').t`Do not ask again`}
                </Label>
            )}
        </>
    );

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleConfirm} {...rest}>
            <ModalTwoHeader
                title={
                    isPhishingAttempt ? c('Title').t`Warning: suspected fake website` : c('Title').t`Link confirmation`
                }
            />
            <ModalTwoContent>{content}</ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                {/* translator: this string is only for blind people, it will be vocalized: confirm opening of link https://link.com */}
                <Button
                    color="norm"
                    type="submit"
                    autoFocus
                    aria-label={c('Action').t`Confirm opening of link ${linkToShow}`}
                    disabled={isPhishingAttempt && !understandRisk}
                >
                    {c('Action').t`Confirm`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
};

export default LinkConfirmationModal;

